type ChainHandler struct { next slog.Handler; key, prev []byte; seq uint64; mu sync.Mutex }

func (h *ChainHandler) Handle(ctx context.Context, r slog.Record) error {
    h.mu.Lock(); defer h.mu.Unlock()                        // one chain owner
    body := canonicalise(r)                                 // stable key order, RFC3339Nano time
    m := hmac.New(sha256.New, h.key)
    m.Write(h.prev)
    m.Write(binary.BigEndian.AppendUint64(nil, h.seq))
    m.Write(body)
    h.prev, h.seq = m.Sum(nil), h.seq+1                     // advance after the durable append
    return h.next.Handle(ctx, tagged{tag: h.prev, body: body}.asRecord())
}
